package com.example.salstats;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point – modernised SALSTATS COBOL program.
 * The STOP RUN equivalent is Spring Boot's ApplicationRunner
 * ({@link com.example.salstats.runner.SalstatsRunner}).
 */
@SpringBootApplication
public class SalstatsApplication {

    public static void main(String[] args) {
        SpringApplication.run(SalstatsApplication.class, args);
    }
}

