package com.example.salstats.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * Application-level beans and filesystem setup.
 * Ensures the output directory exists before the report writer runs,
 * mirroring the OPEN OUTPUT RPT-FILE in MAIN-PARA.
 */
@Configuration
public class AppConfig {

    @Value("${salstats.report.output-path}")
    private String reportOutputPath;

    /**
     * Resolves and exposes the report {@link Path}.
     * Parent directories are created if they do not already exist.
     */
    @Bean
    public Path reportOutputPath() throws IOException {
        Path path = Paths.get(reportOutputPath);
        Files.createDirectories(path.getParent());
        return path;
    }
}

