package com.example.salstats.domain;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import lombok.*;

import java.math.BigDecimal;

/**
 * JPA entity that mirrors the EMPREC copybook used by SALSTATS.
 * Fields match COBOL picture clauses:
 *   EMP-ID     PIC X(10)
 *   EMP-NAME   PIC X(20)
 *   EMP-SALARY PIC 9(07)V99
 */
@Entity
@Table(name = "employees")
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
@ToString
public class Employee {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /** Mirrors EMP-ID PIC X(10) */
    @Column(name = "emp_id", nullable = false, unique = true, length = 10)
    @NotBlank
    @Size(max = 10)
    private String empId;

    /** Mirrors EMP-NAME PIC X(20) */
    @Column(name = "emp_name", nullable = false, length = 20)
    @NotBlank
    @Size(max = 20)
    private String empName;

    /** Mirrors EMP-SALARY PIC 9(07)V99 */
    @Column(name = "emp_salary", nullable = false, precision = 9, scale = 2)
    @NotNull
    @DecimalMin(value = "0.00")
    private BigDecimal empSalary;
}

