package com.example.salstats.domain;

import lombok.*;

import java.math.BigDecimal;

/**
 * Immutable value object that holds the computed payroll statistics.
 * Mirrors the WORKING-STORAGE fields of SALSTATS:
 *   WS-COUNT, WS-TOTAL, WS-AVG, WS-MIN, WS-MAX,
 *   WS-MIN-NAME, WS-MAX-NAME
 */
@Value
@Builder
public class PayrollStatistics {

    /** WS-COUNT PIC 9(05) */
    long employeeCount;

    /** WS-TOTAL PIC 9(09)V99 */
    BigDecimal totalPayroll;

    /** WS-AVG   PIC 9(07)V99 */
    BigDecimal averageSalary;

    /** WS-MIN   PIC 9(07)V99, initial value 9999999.99 */
    BigDecimal minimumSalary;

    /** WS-MIN-NAME PIC X(20) */
    String minimumSalaryEmployeeName;

    /** WS-MAX   PIC 9(07)V99 */
    BigDecimal maximumSalary;

    /** WS-MAX-NAME PIC X(20) */
    String maximumSalaryEmployeeName;
}

