package com.example.salstats.repository;

import com.example.salstats.domain.Employee;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.Optional;
import java.util.stream.Stream;

/**
 * Spring Data JPA repository for {@link Employee}.
 * Replaces the COBOL sequential file READ loop (READ EMP-FILE AT END …)
 * with a scrollable database cursor via {@link Stream}.
 */
@Repository
public interface EmployeeRepository extends JpaRepository<Employee, Long> {

    /**
     * Streams all employees in a single database transaction,
     * equivalent to the COBOL PERFORM UNTIL END-OF-FILE / READ loop.
     * The caller MUST close the stream inside an active transaction.
     */
    @Query("SELECT e FROM Employee e ORDER BY e.id")
    Stream<Employee> streamAllEmployees();

    /**
     * Returns the employee with the lowest salary.
     * Used as a cross-check against the imperative accumulation.
     */
    Optional<Employee> findTopByOrderByEmpSalaryAsc();

    /**
     * Returns the employee with the highest salary.
     */
    Optional<Employee> findTopByOrderByEmpSalaryDesc();

    /**
     * Aggregate query: total payroll (WS-TOTAL).
     */
    @Query("SELECT COALESCE(SUM(e.empSalary), 0) FROM Employee e")
    BigDecimal sumEmpSalary();
}

