package com.example.salstats.service;

import com.example.salstats.domain.Employee;
import com.example.salstats.domain.PayrollStatistics;
import com.example.salstats.repository.EmployeeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.stream.Stream;

/**
 * Computes payroll statistics from the employees table.
 *
 * <p>Business logic is a faithful translation of the COBOL ACCUMULATE
 * paragraph and the IF WS-COUNT > 0 / COMPUTE WS-AVG ROUNDED block
 * in MAIN-PARA.</p>
 *
 * <pre>
 * COBOL → Java mapping
 * ─────────────────────────────────────────────────────────
 * WS-COUNT                  → count       (long)
 * WS-TOTAL                  → total       (BigDecimal)
 * WS-AVG  ROUNDED           → avg         (BigDecimal, HALF_UP)
 * WS-MIN  (init 9999999.99) → min         (BigDecimal)
 * WS-MAX  (init 0)          → max         (BigDecimal)
 * WS-MIN-NAME               → minName     (String)
 * WS-MAX-NAME               → maxName     (String)
 * PERFORM ACCUMULATE        → accumulate() lambda
 * </pre>
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class StatisticsService {

    /** Mirrors COBOL initial value: WS-MIN PIC 9(07)V99 VALUE 9999999.99 */
    private static final BigDecimal INITIAL_MIN = new BigDecimal("9999999.99");

    /** Mirrors COBOL initial value: WS-MAX PIC 9(07)V99 VALUE 0 */
    private static final BigDecimal INITIAL_MAX = BigDecimal.ZERO;

    /** Scale matches PIC 9(07)V99 – two decimal places */
    private static final int SALARY_SCALE = 2;

    private final EmployeeRepository employeeRepository;

    /**
     * Reads every employee record and computes statistics.
     * Mirrors the PERFORM UNTIL END-OF-FILE loop in MAIN-PARA
     * and the ACCUMULATE paragraph.
     *
     * @return computed {@link PayrollStatistics}
     */
    @Transactional(readOnly = true)
    public PayrollStatistics computeStatistics() {

        // ── WORKING-STORAGE initialisations ─────────────────────────
        long   wsCount   = 0L;
        BigDecimal wsTotal = BigDecimal.ZERO.setScale(SALARY_SCALE, RoundingMode.UNNECESSARY);
        BigDecimal wsMin  = INITIAL_MIN;
        BigDecimal wsMax  = INITIAL_MAX;
        String wsMinName  = "";
        String wsMaxName  = "";

        // ── PERFORM UNTIL END-OF-FILE / READ EMP-FILE ───────────────
        try (Stream<Employee> cursor = employeeRepository.streamAllEmployees()) {
            for (Employee emp : (Iterable<Employee>) cursor::iterator) {

                // ── ACCUMULATE ──────────────────────────────────────

                // ADD 1 TO WS-COUNT
                wsCount++;

                // ADD EMP-SALARY TO WS-TOTAL
                wsTotal = wsTotal.add(emp.getEmpSalary());

                // IF EMP-SALARY < WS-MIN
                //   MOVE EMP-SALARY TO WS-MIN
                //   MOVE EMP-NAME   TO WS-MIN-NAME
                if (emp.getEmpSalary().compareTo(wsMin) < 0) {
                    wsMin    = emp.getEmpSalary();
                    wsMinName = trimToCobolWidth(emp.getEmpName(), 20);
                }

                // IF EMP-SALARY > WS-MAX
                //   MOVE EMP-SALARY TO WS-MAX
                //   MOVE EMP-NAME   TO WS-MAX-NAME
                if (emp.getEmpSalary().compareTo(wsMax) > 0) {
                    wsMax    = emp.getEmpSalary();
                    wsMaxName = trimToCobolWidth(emp.getEmpName(), 20);
                }
            }
        }

        // ── IF WS-COUNT > 0 COMPUTE WS-AVG ROUNDED = WS-TOTAL / WS-COUNT
        BigDecimal wsAvg = BigDecimal.ZERO.setScale(SALARY_SCALE, RoundingMode.UNNECESSARY);
        if (wsCount > 0) {
            wsAvg = wsTotal
                    .divide(BigDecimal.valueOf(wsCount),
                            SALARY_SCALE,
                            RoundingMode.HALF_UP);   // ROUNDED → HALF_UP
        }

        log.info("SALSTATS: {} RECORDS PROCESSED", wsCount);

        return PayrollStatistics.builder()
                .employeeCount(wsCount)
                .totalPayroll(wsTotal)
                .averageSalary(wsAvg)
                .minimumSalary(wsMin)
                .minimumSalaryEmployeeName(wsMinName)
                .maximumSalary(wsMax)
                .maximumSalaryEmployeeName(wsMaxName)
                .build();
    }

    /**
     * Truncates or right-pads a name to exactly {@code width} characters,
     * reproducing COBOL's MOVE EMP-NAME TO WS-MIN-NAME (PIC X(20)) behaviour.
     */
    private String trimToCobolWidth(String value, int width) {
        if (value == null) {
            return " ".repeat(width);
        }
        if (value.length() >= width) {
            return value.substring(0, width);
        }
        return String.format("%-" + width + "s", value);
    }
}

