package com.example.salstats.service;

import com.example.salstats.domain.PayrollStatistics;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * Writes the payroll statistics report.
 *
 * <p>Faithfully reproduces the WRITE-REPORT paragraph in SALSTATS,
 * including the COBOL edited picture formats:
 * <pre>
 *   OUT-AMOUNT  PIC ZZZ,ZZZ,ZZ9.99   → {@link #formatAmount(BigDecimal)}
 *   CNT-VALUE   PIC ZZZ,ZZZ,ZZ9      → {@link #formatCount(long)}
 *   OUT-LABEL   PIC X(24)             → left-padded to 24 chars
 *   OUT-NAME    PIC X(20)             → right of amount field
 * </pre>
 * </p>
 *
 * <p>The 80-character line width (RPT-LINE PIC X(80)) is enforced
 * by {@link #rptLine(String)}.</p>
 */
@Slf4j
@Service
@RequiredArgsConstructor
public class ReportService {

    /** Mirrors RPT-LINE PIC X(80) */
    private static final int RPT_LINE_WIDTH = 80;

    /** Mirrors WS-SEP PIC X(60) VALUE ALL "=" */
    private static final String SEPARATOR = "=".repeat(60);

    /** Mirrors OUT-LABEL PIC X(24) */
    private static final int LABEL_WIDTH = 24;

    /** Mirrors OUT-AMOUNT PIC ZZZ,ZZZ,ZZ9.99  (13 chars including sign placeholder) */
    private static final String AMOUNT_PATTERN  = "ZZZ,ZZZ,ZZ9.99";

    /** Mirrors CNT-VALUE PIC ZZZ,ZZZ,ZZ9 (11 chars) */
    private static final String COUNT_PATTERN   = "ZZZ,ZZZ,ZZ9";

    private final Path reportOutputPath;

    /**
     * Generates the complete report file.
     * Mirrors the WRITE-REPORT paragraph and the OPEN / CLOSE OUTPUT RPT-FILE
     * instructions in MAIN-PARA.
     *
     * @param stats computed payroll statistics
     */
    public void writeReport(PayrollStatistics stats) {
        log.info("Writing payroll statistics report to {}", reportOutputPath);

        try (BufferedWriter writer =
                     Files.newBufferedWriter(reportOutputPath, StandardCharsets.UTF_8)) {

            // WRITE RPT-LINE FROM "PAYROLL STATISTICS"
            writeLine(writer, rptLine("PAYROLL STATISTICS"));

            // WRITE RPT-LINE FROM WS-SEP
            writeLine(writer, rptLine(SEPARATOR));

            // MOVE "EMPLOYEE COUNT:" TO CNT-LABEL
            // MOVE WS-COUNT TO CNT-VALUE
            // WRITE RPT-LINE FROM CNT-LINE
            String cntLine = String.format("%-" + LABEL_WIDTH + "s%s",
                    "EMPLOYEE COUNT:",
                    formatCount(stats.getEmployeeCount()));
            writeLine(writer, rptLine(cntLine));

            // MOVE SPACES TO OUT-LINE
            // MOVE "TOTAL PAYROLL:" TO OUT-LABEL
            // MOVE WS-TOTAL TO OUT-AMOUNT
            // WRITE RPT-LINE FROM OUT-LINE
            writeLine(writer, buildAmountLine("TOTAL PAYROLL:",
                    stats.getTotalPayroll(), null));

            // MOVE SPACES TO OUT-LINE
            // MOVE "AVERAGE SALARY:" TO OUT-LABEL
            // MOVE WS-AVG TO OUT-AMOUNT
            // WRITE RPT-LINE FROM OUT-LINE
            writeLine(writer, buildAmountLine("AVERAGE SALARY:",
                    stats.getAverageSalary(), null));

            // MOVE "MINIMUM SALARY:" TO OUT-LABEL
            // MOVE WS-MIN TO OUT-AMOUNT
            // MOVE WS-MIN-NAME TO OUT-NAME
            // WRITE RPT-LINE FROM OUT-LINE
            writeLine(writer, buildAmountLine("MINIMUM SALARY:",
                    stats.getMinimumSalary(),
                    stats.getMinimumSalaryEmployeeName()));

            // MOVE "MAXIMUM SALARY:" TO OUT-LABEL
            // MOVE WS-MAX TO OUT-AMOUNT
            // MOVE WS-MAX-NAME TO OUT-NAME
            // WRITE RPT-LINE FROM OUT-LINE
            writeLine(writer, buildAmountLine("MAXIMUM SALARY:",
                    stats.getMaximumSalary(),
                    stats.getMaximumSalaryEmployeeName()));

            // WRITE RPT-LINE FROM WS-SEP
            writeLine(writer, rptLine(SEPARATOR));

        } catch (IOException ex) {
            throw new UncheckedIOException("Failed to write report: " + reportOutputPath, ex);
        }

        log.info("Report written successfully.");
    }

    // ── Private helpers ──────────────────────────────────────────────────────

    /**
     * Builds an OUT-LINE:
     * <pre>
     *   OUT-LABEL  PIC X(24)
     *   OUT-AMOUNT PIC ZZZ,ZZZ,ZZ9.99
     *   FILLER     PIC X(02) VALUE SPACES
     *   OUT-NAME   PIC X(20)   (optional)
     * </pre>
     */
    private String buildAmountLine(String label, BigDecimal amount, String name) {
        // MOVE SPACES TO OUT-LINE  → start from blank
        StringBuilder sb = new StringBuilder();

        // OUT-LABEL PIC X(24)
        sb.append(String.format("%-" + LABEL_WIDTH + "s", label));

        // OUT-AMOUNT PIC ZZZ,ZZZ,ZZ9.99
        sb.append(formatAmount(amount));

        // FILLER PIC X(02) VALUE SPACES
        sb.append("  ");

        // OUT-NAME PIC X(20)
        if (name != null && !name.isBlank()) {
            sb.append(String.format("%-20s", name));
        }

        return rptLine(sb.toString());
    }

    /**
     * Truncates / pads to exactly {@value #RPT_LINE_WIDTH} characters,
     * mirroring RPT-LINE PIC X(80).
     */
    private String rptLine(String content) {
        if (content.length() >= RPT_LINE_WIDTH) {
            return content.substring(0, RPT_LINE_WIDTH);
        }
        return String.format("%-" + RPT_LINE_WIDTH + "s", content);
    }

    private void writeLine(BufferedWriter writer, String line) throws IOException {
        writer.write(line);
        writer.newLine();
    }

    /**
     * Formats a {@link BigDecimal} using COBOL edited picture ZZZ,ZZZ,ZZ9.99.
     * Leading zeros are suppressed (Z) except for the final integer digit (9).
     * Negative values are not expected per the COBOL CHECK constraint but are
     * handled gracefully.
     */
    private String formatAmount(BigDecimal value) {
        // Build a standard DecimalFormat that matches ZZZ,ZZZ,ZZ9.99
        // Pattern: #,##0.00 gives us the 9 and Z behaviour
        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
        DecimalFormat df = new DecimalFormat("#,##0.00", symbols);
        df.setMinimumIntegerDigits(1);   // the '9' (last integer digit always shown)
        df.setGroupingUsed(true);
        df.setGroupingSize(3);
        // Right-align within the picture width (14 chars: "ZZZ,ZZZ,ZZ9.99")
        String formatted = df.format(value);
        return String.format("%14s", formatted);
    }

    /**
     * Formats a long count using COBOL edited picture ZZZ,ZZZ,ZZ9.
     */
    private String formatCount(long value) {
        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.US);
        DecimalFormat df = new DecimalFormat("#,##0", symbols);
        df.setGroupingUsed(true);
        df.setGroupingSize(3);
        // Right-align within the picture width (11 chars: "ZZZ,ZZZ,ZZ9")
        String formatted = df.format(value);
        return String.format("%11s", formatted);
    }
}

