package com.example.salstats.runner;

import com.example.salstats.domain.PayrollStatistics;
import com.example.salstats.service.ReportService;
import com.example.salstats.service.StatisticsService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.boot.ExitCodeGenerator;
import org.springframework.boot.SpringApplication;
import org.springframework.context.ApplicationContext;
import org.springframework.stereotype.Component;

/**
 * Orchestrates the SALSTATS workflow.
 *
 * <p>This is a direct translation of the MAIN-PARA paragraph:</p>
 * <pre>
 * MAIN-PARA.
 *     OPEN INPUT EMP-FILE OUTPUT RPT-FILE         ← handled by Spring / AppConfig
 *     PERFORM UNTIL END-OF-FILE                   ← StatisticsService.computeStatistics()
 *         READ EMP-FILE …
 *         PERFORM ACCUMULATE
 *     END-PERFORM
 *     IF WS-COUNT > 0 COMPUTE WS-AVG ROUNDED …   ← StatisticsService
 *     PERFORM WRITE-REPORT                        ← ReportService.writeReport()
 *     CLOSE EMP-FILE RPT-FILE                     ← try-with-resources in services
 *     DISPLAY "SALSTATS: " WS-COUNT " RECORDS …" ← log.info below
 *     STOP RUN.                                   ← Spring exits after run()
 * </pre>
 */
@Slf4j
@Component
@RequiredArgsConstructor
public class SalstatsRunner implements ApplicationRunner {

    private final StatisticsService statisticsService;
    private final ReportService     reportService;
    private final ApplicationContext applicationContext;

    @Override
    public void run(ApplicationArguments args) {

        // PERFORM UNTIL END-OF-FILE + PERFORM ACCUMULATE
        // + IF WS-COUNT > 0 COMPUTE WS-AVG ROUNDED
        PayrollStatistics stats = statisticsService.computeStatistics();

        // PERFORM WRITE-REPORT
        reportService.writeReport(stats);

        // DISPLAY "SALSTATS: " WS-COUNT " RECORDS PROCESSED"
        log.info("SALSTATS: {} RECORDS PROCESSED", stats.getEmployeeCount());
