import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import java.util.stream.Stream;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.when;

/**
 * Unit tests for {@link StatisticsService}.
 * Verifies that every business rule from the COBOL ACCUMULATE
 * paragraph and the COMPUTE WS-AVG ROUNDED statement is preserved.
 */
@ExtendWith(MockitoExtension.class)
class StatisticsServiceTest {

    @Mock
    private EmployeeRepository employeeRepository;

    @InjectMocks
    private StatisticsService statisticsService;

    private Employee alice;
    private Employee bob;
    private Employee carol;

    @BeforeEach
    void setUp() {
        alice = Employee.builder()
                .id(1L).empId("E001")
                .empName("Alice")
                .empSalary(new BigDecimal("50000.00"))
                .build();

        bob = Employee.builder()
                .id(2L).empId("E002")
                .empName("Bob")
                .empSalary(new BigDecimal("75000.00"))
                .build();

        carol = Employee.builder()
                .id(3L).empId("E003")
                .empName("Carol")
                .empSalary(new BigDecimal("30000.50"))
                .build();
    }

    @Test
    void computeStatistics_withThreeEmployees_returnsCorrectAggregates() {
        when(employeeRepository.streamAllEmployees())
                .thenReturn(Stream.of(alice, bob, carol));

        PayrollStatistics stats = statisticsService.computeStatistics();

        // WS-COUNT = 3
        assertThat(stats.getEmployeeCount()).isEqualTo(3L);

        // WS-TOTAL = 50000.00 + 75000.00 + 30000.50 = 155000.50
        assertThat(stats.getTotalPayroll())
                .isEqualByComparingTo(new BigDecimal("155000.50"));

        // WS-AVG ROUNDED = 155000.50 / 3 = 51666.83 (HALF_UP)
        assertThat(stats.getAverageSalary())
                .isEqualByComparingTo(new BigDecimal("51666.83"));

        // WS-MIN = 30000.50, WS-MIN-NAME = "Carol"
        assertThat(stats.getMinimumSalary())
                .isEqualByComparingTo(new BigDecimal("30000.50"));
        assertThat(stats.getMinimumSalaryEmployeeName().trim()).isEqualTo("Carol");

        // WS-MAX = 75000.00, WS-MAX-NAME = "Bob"
        assertThat(stats.getMaximumSalary())
                .isEqualByComparingTo(new BigDecimal("75000.00"));
        assertThat(stats.getMaximumSalaryEmployeeName().trim()).isEqualTo("Bob");
    }

    @Test
    void computeStatistics_withNoEmployees_returnsZeroStats() {
        when(employeeRepository.streamAllEmployees())
                .thenReturn(Stream.empty());

        PayrollStatistics stats = statisticsService.computeStatistics();

        // WS-COUNT = 0  → WS-AVG stays 0 (IF WS-COUNT > 0 branch not taken)
        assertThat(stats.getEmployeeCount()).isZero();
        assertThat(stats.getAverageSalary()).isEqualByComparingTo(BigDecimal.ZERO);
        assertThat(stats.getTotalPayroll()).isEqualByComparingTo(BigDecimal.ZERO);
    }

    @Test
    void computeStatistics_withSingleEmployee_minAndMaxAreSame() {
        when(employeeRepository.streamAllEmployees())
                .thenReturn(Stream.of(alice));

        PayrollStatistics stats = statisticsService.computeStatistics();

        assertThat(stats.getMinimumSalary()).isEqualByComparingTo(alice.getEmpSalary());
        assertThat(stats.getMaximumSalary()).isEqualByComparingTo(alice.getEmpSalary());
        assertThat(stats.getMinimumSalaryEmployeeName().trim()).isEqualTo("Alice");
        assertThat(stats.getMaximumSalaryEmployeeName().trim()).isEqualTo("Alice");
    }

    @Test
    void computeStatistics_averageIsRoundedHalfUp() {
        // 1 + 2 = 3, avg = 3/2 = 1.50 (exact, no rounding needed)
        Employee e1 = Employee.builder().id(1L).empId("X1")
                .empName("One").empSalary(new BigDecimal("1.00")).build();
        Employee e2 = Employee.builder().id(2L).empId("X2")
                .empName("Two").empSalary(new BigDecimal("2.00")).build();

        when(employeeRepository.streamAllEmployees())
                .thenReturn(Stream.of(e1, e2));

        PayrollStatistics stats = statisticsService.computeStatistics();

        // 3.00 / 2 = 1.50
        assertThat(stats.getAverageSalary())
                .isEqualByComparingTo(new BigDecimal("1.50"));
    }
